INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1893,1,'2025-07-20 13:17:10','2025-07-20 20:17:10','<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\">Invisalign</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\">Clareamento Dental e Limpeza</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\">Digital Smile Design</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\">Implantes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\">Harmonização Orofacial</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Serviços','','inherit','closed','closed','','1887-revision-v1','','','2025-07-20 13:17:10','2025-07-20 20:17:10','',1887,'https://primeodontologia.com.br/?p=1893',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1894,1,'2025-07-20 13:20:12','2025-07-20 20:20:12','<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Invisalign</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Clareamento Dental e Limpeza</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Digital Smile Design</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Digital</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Estética</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Preventiva</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Restauradora</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Ortodontia</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Prótese Dentária</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Harmonização Orofacial</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Serviços','','inherit','closed','closed','','1887-revision-v1','','','2025-07-20 13:20:12','2025-07-20 20:20:12','',1887,'https://primeodontologia.com.br/?p=1894',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (1895,1,'2025-07-20 13:22:04','2025-07-20 20:22:04','<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\"><strong>Sobre Nós</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">A <strong>Prime Odontologia</strong> é um Centro Orofacial criado com o objetivo de proporcionar sorrisos com saúde, qualidade de vida e bem estar aos pacientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Praticamos o atendimento odontológico integrado, no mesmo local, entre todas as especialidades da clínica odontológica.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Staff </strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">Contamos com uma equipe de profissionais cirurgiões dentistas altamente qualificados e prestando atendimento humanizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">Atuando de forma integrada de acordo com as necessidades de cada paciente, ampliando os resultados e encurtando caminhos ao utilizar modernas técnicas de diagnóstico e planejamento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A interação entre os especialistas durante o atendimento odontológico é fundamental para alcançarmos resultados precisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Temos como filosofia, a prevenção para adultos e crianças, pois acreditamos que a prevenção na odontologia é o suporte fundamental para a manutenção de um sorriso saudável e consequente bem-estar dos nossos pacientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Valorizamos a importância de planejarmos em equipe todos os casos odontológicos, com o auxílio de toda infraestrutura e tecnologia. Utilizamos ferramentas modernas, como o Digital Smile Design, que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Diagnóstico e planejamento em equipe com auxílio de infraestrutura e tecnologia de todos os casos: Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Estrutura Clínica</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">Preservamoa o nosso ambiente de acordo, com rigorosas normas e protocolos de biossegurança.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">Nos tempos atuais, sabemos o quanto é imprescindível à saúde bucal, sendo ela um dos principais reguladores da saúde e bem estar. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">Dessa maneira, almejamos sanar as expectativas de nossos pacientes com foco para na prevenção e manutenção da saúde humana.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\"><strong>Atendimento preventivo para adultos e crianças: Acreditamos que a prevenção é o suporte fundamental para a manutenção de um sorriso saudável e para o bem-estar dos nossos pacientes.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Consulta Odontológica</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Levantamento de necessidade da saúde bucal</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Limpeza Dentári</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Cirurgia para Remoção de Dentes Siso</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Cirurgia para Remoção de Dentes terceiros molares</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Endodontia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Tratamento de Canal</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Prevenção Odontológica</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Ortodontia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Aparelhos Ortodônticos</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Aparelho dentário tradicional</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Aparelho dentário estético</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Invisalign</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Digital Smile Design</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Desenho Digital do Sorriso</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Reabilitação Oral</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Implantes dentários</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Facetas de Porcelana</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Odontologia Estética</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Clareamento Dental &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Disfunção Temporomandibular</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Periodontia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Plástica Gengival</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- Odontologia Restauradora</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- CONHEÇA NOSSA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">EQUIPE</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\"><strong>Dr. André Almeida</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">O fundador da Prime Odontologia é graduado em Odontologia pela UFMG e possui residência em São Paulo e em Sydney no conceito de <em>Digital Smile Design</em>. Dentista em Belo Horizonte, desde 2011 é especialista em Prótese Dentária e Ortodontia Funcional dos Maxilares. Adota o tratamento humanizado e integrado em seus atendimentos. &nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">- NÃO FIQUE 