 -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Levantamento de Necessidade da Saúde Bucal</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Harmonização Orofacial</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Serviços','','inherit','closed','closed','','1887-revision-v1','','','2025-07-20 13:33:29','2025-07-20 20:33:29','',1887,'https://primeodontologia.com.br/?p=1902',0,'revision','',0);
