INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2092,1,'2025-08-25 17:48:23','2025-08-26 00:48:23','<!-- wp:video {\"id\":1826} -->\n<figure class=\"wp-block-video\"><video controls src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/1603_PPL-Animado_Como_Nao_Invisa-1.mp4\"></video><figcaption class=\"wp-element-caption\"><strong>O seu sorriso Invisalign</strong></figcaption></figure>\n<!-- /wp:video -->\n\n<!-- wp:video {\"id\":1825} -->\n<figure class=\"wp-block-video\"><video controls src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/1506_Feed-Animado_1080x1080_doctors-1.mp4\"></video><figcaption class=\"wp-element-caption\"><strong>Tecnológico Personalizado e mais rápido</strong></figcaption></figure>\n<!-- /wp:video -->\n\n<!-- wp:video {\"id\":1824} -->\n<figure class=\"wp-block-video\"><video controls src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/0811_invisalign_reels_como-s-o-feitos_v3-1.mp4\"></video><figcaption class=\"wp-element-caption\"><strong>Invisalign no seu dia a dia</strong></figcaption></figure>\n<!-- /wp:video -->\n\n<!-- wp:paragraph {\"className\":\"MsoNormal\"} -->\n<p class=\"MsoNormal\">A <strong>Prime Odontologia</strong> é um Centro Orofacial criado com o objetivo de proporcionar sorrisos com saúde, qualidade de vida e bem estar aos pacientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Praticamos o atendimento odontológico integrado, no mesmo local, entre todas as especialidades da clínica odontológica.</p>\n<!-- /wp:paragraph -->','Sobre Nós','dentista-em-belo-horizonte','inherit','closed','closed','','1208-revision-v1','','','2025-08-25 17:48:23','2025-08-26 00:48:23','',1208,'https://primeodontologia.com.br/?p=2092',0,'revision','',0);
