INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2094,1,'2025-08-29 15:17:16','2025-08-29 22:17:16','<!-- wp:paragraph -->\n<p><strong>Thiago Ribeiro</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Sempre faço minha limpeza dentária na Prime Odontologia.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Nathalia Abreu</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cuido do meu sorriso com a ortodontia do Invisalign.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Fernando Lima</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Realizei o tratamento com Invisalign e gostei bastante do resultado e agora estamos fazemos a proxima etapa do tratamento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Depoimentos','','inherit','closed','closed','','1209-revision-v1','','','2025-08-29 15:17:16','2025-08-29 22:17:16','',1209,'https://primeodontologia.com.br/?p=2094',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2096,1,'2025-08-29 15:24:15','2025-08-29 22:24:15','<!-- wp:paragraph -->\n<p>Controlamos o nosso ambiente de acordo, com rigorosas normas e protocolos de biossegurança.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Nos tempos atuais, sabemos o quanto é imprescindível à saúde bucal, sendo ela um dos principais reguladores da saúde e bem estar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dessa maneira, almejamos sanar as expectativas de nossos pacientes com foco para na prevenção e manutenção da saúde bucal e sistemica.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Atendimento preventivo para adultos e crianças.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> Acreditamos que a prevenção é o suporte fundamental para a manutenção de um sorriso saudável e para a saude dos nossos pacientes.</p>\n<!-- /wp:paragraph -->','Estrutura Clínica','Estrutura Clínica','inherit','closed','closed','','1420-revision-v1','','','2025-08-29 15:24:15','2025-08-29 22:24:15','',1420,'https://primeodontologia.com.br/?p=2096',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2098,1,'2025-08-29 15:28:12','2025-08-29 22:28:12','Realizamos tratamentos com aparelhos convencionais e o discreto Invisalign.\n\n<img class=\"size-full wp-image-2042\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_1-1-1.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2041\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_2-2.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2040\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_3.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2043\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_4-1.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2045\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_5-1.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2050\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_6-1.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2046\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_7-1.png\" width=\"1080\" height=\"1080\" /><img class=\"size-full wp-image-2044\" src=\"https://primeodontologia.com.br/wp-content/uploads/2025/07/feed-estatico_nunca-tarde-para-sorrir_8-1-1.png\" width=\"1080\" height=\"1080\" />','Blog do Dentista','Invisalign','inherit','closed','closed','','25-revision-v1','','','2025-08-29 15:28:12','2025-08-29 22:28:12','',25,'https://primeodontologia.com.br/?p=2098',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2100,1,'2025-08-29 15:31:35','2025-08-29 22:31:35','<span lang=\"PT-BR\" style=\"font-size: 12.0pt;\"><b style=\"mso-bidi-font-weight: normal;\">Missão</b></span>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">Atuar de forma integrada em conformidade com as necessidades de cada\npaciente, ampliando os resultados e encurtando os caminhos ao utilizar técnicas\nmodernas de diagnóstico e planejamento, com rigorosas normas de biossegurança.</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\"><b style=\"mso-bidi-font-weight: normal;\">Visão</b></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">A saúde bucal é um dos principais reguladores da saúde sistêmica, sendo\nimprescindível atualmente. Dessa maneira, almejamos sanar as expectativas de\nnossos pacientes com o foco na abordagem transdisciplinar da saúde humana.</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\"><b style=\"mso-bidi-font-weight: normal;\">Valores</b></span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">Priorizamos o atendimento preventivo para adultos e assim como crianças. </span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">Acreditamos que a prevenção é o suporte fundamental para a manutenção de um sorriso saudável e\npara o bem-estar dos nossos pacientes.</span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">Realizamos diagnóstico e planejamento em equipe com auxílio de infraestrutura e\ntecnologia de todos os casos. </span></p>\n<p class=\"MsoNormal\" style=\"margin-bottom: 0inline-height:normal; text-align: left;\"><span lang=\"PT-BR\" style=\"font-size: 12.0pt;\">Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.</span></p>','Nossa Filosofia','nossa visão','inherit','closed','closed','','1419-revision-v1','','','2025-08-29 15:31:35','2025-08-29 22:31:35','',1419,'https://primeodontologia.com.br/?p=2100',0,'revision','',0);
