INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2110,1,'2025-08-29 15:46:02','2025-08-29 22:46:02','<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Invisalign</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Consulta Odontológica</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Cirurgia para remoção do Dente Siso, Terceiro Molar</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Clareamento Dental</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Digital Smile Design, O desenho digital do Sorriso</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Disfunção Temporomandibular</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Endodontia e o tratamento do canal dentário</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Facetas de Porcelana</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Digital</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Estética</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Preventiva</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Restauradora</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Ortodontia</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Implantes Dentários</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Limpeza Dentária</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Prótese Dentária</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Implantes Dentários</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Periodontia</strong> <strong>e Plástica Gengival</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Prevenção Odontológica</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Reabilitação Oral</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Levantamento de Necessidade da Saúde Bucal</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Harmonização Orofacial</strong></p>\n<!-- /wp:paragraph -->','Tratamentos em Odontologia','','inherit','closed','closed','','1887-revision-v1','','','2025-08-29 15:46:02','2025-08-29 22:46:02','',1887,'https://primeodontologia.com.br/?p=2110',0,'revision','',0);
