INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2174,1,'2025-08-31 09:47:15','2025-08-31 16:47:15','{\n    \"onepress::onepress_about_desc\": {\n        \"value\": \"Ficou mais f\\u00e1cil o acesso ao tratamento Invisalign.\\nComo cada sorriso \\u00e9 \\u00fanico, apenas um dentista pode determinar o custo do seu tratamento Invisalign. \\nConverse com o dentista para obter mais informa\\u00e7\\u00f5es.\\n\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 16:47:15\"\n    },\n    \"onepress::onepress_about_title\": {\n        \"value\": \"Tratamento Invisalign\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 16:47:15\"\n    },\n    \"onepress::onepress_about_subtitle\": {\n        \"value\": \"Alinhador transparente e moderno\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 16:47:15\"\n    }\n}','','','trash','closed','closed','','64104078-198f-45b7-b7e7-4d64fca73c70','','','2025-08-31 09:47:15','2025-08-31 16:47:15','',0,'https://primeodontologia.com.br/?p=2174',0,'customize_changeset','',0);
