INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2283,1,'2025-08-31 11:09:02','2025-08-31 18:09:02','<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Invisalign</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Consulta Odontológica</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Cirurgia para remoção do Dente Siso, Terceiro Molar</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Clareamento Dental</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Digital Smile Design, O desenho digital do Sorriso</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Disfunção Temporomandibular</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Endodontia e o tratamento do canal dentário</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Facetas de Porcelana</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"backgroundColor\":\"cyan-bluish-gray\"} -->\n<p class=\"has-cyan-bluish-gray-background-color has-background\"><strong>Odontologia Digital</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragrap