INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2411,1,'2025-08-31 13:36:14','2025-08-31 20:36:14','{\n    \"onepress::onepress_counter_boxes\": {\n        \"value\": \"\\\"_items%5B0%5D%5Btitle%5D=Tratamentos%20Invisalign&_items%5B0%5D%5Bnumber%5D=90&_items%5B0%5D%5Bunit_before%5D=&_items%5B0%5D%5Bunit_after%5D=&_items%5B1%5D%5Btitle%5D=Evolucao%20do%20tratamento&_items%5B1%5D%5Bnumber%5D=80&_items%5B1%5D%5Bunit_before%5D=&_items%5B1%5D%5Bunit_after%5D=%25&_items%5B2%5D%5Btitle%5D=Servicos%20em%20Odontologia&_items%5B2%5D%5Bnumber%5D=26&_items%5B2%5D%5Bunit_before%5D=&_items%5B2%5D%5Bunit_after%5D=&_items%5B3%5D%5Btitle%5D=Custo%20da%20Consulta%20com%20o%20dentista%20e%20limpeza%20dos%20dentes&_items%5B3%5D%5Bnumber%5D=180&_items%5B3%5D%5Bunit_before%5D=R%24&_items%5B3%5D%5Bunit_after%5D=\\\"\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:36:14\"\n    }\n}','','','trash','closed','closed','','1e2f7ea4-db1e-4556-90ff-6273e8fbf64a','','','2025-08-31 13:36:14','2025-08-31 20:36:14','',0,'https://primeodontologia.com.br/?p=2411',0,'customize_changeset','',0);
