INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2413,1,'2025-08-31 13:37:07','2025-08-31 20:37:07','{\n    \"onepress::onepress_team_subtitle\": {\n        \"value\": \"Nossos Dentistas\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:37:07\"\n    }\n}','','','trash','closed','closed','','54cbb40a-db3f-42cf-a45c-9c505ecdf70f','','','2025-08-31 13:37:07','2025-08-31 20:37:07','',0,'https://primeodontologia.com.br/?p=2413',0,'customize_changeset','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2414,1,'2025-08-31 13:39:50','2025-08-31 20:39:50','{\n    \"onepress::onepress_team_title\": {\n        \"value\": \"Conhe\\u00e7a a nossa estrutura\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:38:59\"\n    },\n    \"onepress::onepress_team_subtitle\": {\n        \"value\": \"Nossa Equipe\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:38:59\"\n    },\n    \"onepress::onepress_team_desc\": {\n        \"value\": \"Contamos com uma equipe de profissionais cirurgi\\u00f5es dentistas altamente qualificados e prestando atendimento humanizado.\\n\\nAtuando de forma integrada de acordo com as necessidades de cada paciente, ampliando os resultados e encurtando caminhos ao utilizar modernas t\\u00e9cnicas de diagn\\u00f3stico e planejamento.\\n\\nA intera\\u00e7\\u00e3o entre os especialistas durante o atendimento odontol\\u00f3gico \\u00e9 fundamental para alcan\\u00e7armos resultados precisos.\\n\\nTemos como filosofia, a preven\\u00e7\\u00e3o para adultos e crian\\u00e7as, pois acreditamos que a preven\\u00e7\\u00e3o na odontologia \\u00e9 o suporte fundamental para a manuten\\u00e7\\u00e3o de um sorriso saud\\u00e1vel e consequente bem-estar dos nossos pacientes.\\n\\nValorizamos a import\\u00e2ncia de planejarmos em equipe todos os casos odontol\\u00f3gicos, com o aux\\u00edlio de toda infraestrutura e tecnologia. Utilizamos ferramentas modernas, como o Digital Smile Design, que nos permitem arquitetar e transformar sorrisos.\\n\\nDiagn\\u00f3stico e planejamento em equipe com aux\\u00edlio de infraestrutura e tecnologia de todos os casos: Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.\\n\\nDr. Andr\\u00e9 Almeida\\n\\nO fundador da Prime Odontologia \\u00e9 graduado em Odontologia pela UFMG e possui resid\\u00eancia em S\\u00e3o Paulo e em Sydney no conceito de Digital Smile Design. \\n\\nAtua como Dentista em Belo Horizonte, desde 2011 e \\u00e9 especialista em Pr\\u00f3tese Dent\\u00e1ria e Ortodontia Funcional dos Maxilares.\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:39:50\"\n    }\n}','','','trash','closed','closed','','6bca0e27-5d5b-457f-be4c-178af3117a64','','','2025-08-31 13:39:50','2025-08-31 20:39:50','',0,'https://primeodontologia.com.br/?p=2414',0,'customize_changeset','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2415,1,'2025-08-31 13:41:50','2025-08-31 20:41:50','{\n    \"onepress::onepress_team_title\": {\n        \"value\": \"Nossa Equipe \",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:40:15\"\n    },\n    \"onepress::onepress_team_subtitle\": {\n        \"value\": \"Conhe\\u00e7a a nossa estrutura\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:40:15\"\n    },\n    \"onepress::onepress_team_desc\": {\n        \"value\": \"Contamos com uma equipe de profissionais cirurgi\\u00f5es dentistas altamente qualificados e prestando atendimento humanizado.\\n\\nAtuando de forma integrada de acordo com as necessidades de cada paciente, ampliando os resultados e encurtando caminhos ao utilizar modernas t\\u00e9cnicas de diagn\\u00f3stico e planejamento.\\n\\nA intera\\u00e7\\u00e3o entre os especialistas durante o atendimento odontol\\u00f3gico \\u00e9 fundamental para alcan\\u00e7armos resultados precisos.\\n\\nTemos como filosofia, a preven\\u00e7\\u00e3o para adultos e crian\\u00e7as, pois acreditamos que a preven\\u00e7\\u00e3o na odontologia \\u00e9 o suporte fundamental para a manuten\\u00e7\\u00e3o de um sorriso saud\\u00e1vel e consequente bem-estar dos nossos pacientes.\\n\\nValorizamos a import\\u00e2ncia de planejarmos em equipe todos os casos odontol\\u00f3gicos, com o aux\\u00edlio de toda infraestrutura e tecnologia. Utilizamos ferramentas modernas, como o Digital Smile Design, que nos permitem arquitetar e transformar sorrisos.\\n\\nDiagn\\u00f3stico e planejamento em equipe com aux\\u00edlio de infraestrutura e tecnologia de todos os casos: Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.\\n\\n\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-08-31 20:40:59\"\n    }\n}','','','trash','closed','closed','','8f2ea394-c459-4942-b2f1-be41c8ea1afb','','','2025-08-31 13:41:50','2025-08-31 20:41:50','',0,'https://primeodontologia.com.br/?p=2415',0,'customize_changeset','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2416,1,'2025-08-31 13:41:09','2025-08-31 20:41:09','<!-- wp:paragraph -->\n<p><strong>Conheça a nossa equipe</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Contamos com uma equipe de profissionais cirurgiões dentistas altamente qualificados e prestando atendimento humanizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Atuando de forma integrada de acordo com as necessidades de cada paciente, ampliando os resultados e encurtando caminhos ao utilizar modernas técnicas de diagnóstico e planejamento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A interação entre os especialistas durante o atendimento odontológico é fundamental para alcançarmos resultados precisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Temos como filosofia, a prevenção para adultos e crianças, pois acreditamos que a prevenção na odontologia é o suporte fundamental para a manutenção de um sorriso saudável e consequente bem-estar dos nossos pacientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Valorizamos a importância de planejarmos em equipe todos os casos odontológicos, com o auxílio de toda infraestrutura e tecnologia. Utilizamos ferramentas modernas, como o Digital Smile Design, que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Diagnóstico e planejamento em equipe com auxílio de infraestrutura e tecnologia de todos os casos: Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Dr. André Almeida</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>O fundador da Prime Odontologia é graduado em Odontologia pela UFMG e possui residência em São Paulo e em Sydney no conceito de <em>Digital Smile Design</em>. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Dr. André Almeida</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>O fundador da Prime Odontologia é graduado em Odontologia pela UFMG e possui residência em São Paulo e em Sydney no conceito de Digital Smile Design.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Atua como Dentista em Belo Horizonte, desde 2011 e é especialista em Prótese Dentária e especialista em Ortodontia Funcional dos Maxilares desde 2021.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Staff','Staff','inherit','closed','closed','','1221-revision-v1','','','2025-08-31 13:41:09','2025-08-31 20:41:09','',1221,'https://primeodontologia.com.br/?p=2416',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (2418,1,'2025-08-31 13:41:44','2025-08-31 20:41:44','<!-- wp:paragraph -->\n<p><strong>Conheça a nossa equipe</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Contamos com uma equipe de profissionais cirurgiões dentistas altamente qualificados e prestando atendimento humanizado.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Atuando de forma integrada de acordo com as necessidades de cada paciente, ampliando os resultados e encurtando caminhos ao utilizar modernas técnicas de diagnóstico e planejamento.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A interação entre os especialistas durante o atendimento odontológico é fundamental para alcançarmos resultados precisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Temos como filosofia, a prevenção para adultos e crianças, pois acreditamos que a prevenção na odontologia é o suporte fundamental para a manutenção de um sorriso saudável e consequente bem-estar dos nossos pacientes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Valorizamos a importância de planejarmos em equipe todos os casos odontológicos, com o auxílio de toda infraestrutura e tecnologia. Utilizamos ferramentas modernas, como o Digital Smile Design, que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Diagnóstico e planejamento em equipe com auxílio de infraestrutura e tecnologia de todos os casos: Utilizamos ferramentas modernas que nos permitem arquitetar e transformar sorrisos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Dr. André Almeida</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":1538,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://primeodontologia.com.br/wp-content/uploads/2024/12/img_0765-1-1024x1024.jpg\" alt=\"\" class=\"wp-image-1538\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>O fundador da Prime Odontologia é graduado em Odontologia pela UFMG e possui residência em São Paulo e em Sydney no conceito de Digital Smile Design.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Atua como Dentista em Belo Horizonte, desde 2011 e é especialista em Prótese Dentária e especialista em Ortodontia Funcional dos Maxilares desde 2021.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Staff','Staff','inherit','closed','closed','','1221-revision-v1','','','2025-08-31 13:41:44','2025-08-31 20:41:44','',1221,'https://primeodontologia.com.br/?p=2418',0,'revision','',0);
