  `zbs_site` int(11) DEFAULT NULL,
  `zbs_team` int(11) DEFAULT NULL,
  `zbs_owner` int(11) NOT NULL,
  `zbstl_objtype` int(4) NOT NULL,
  `zbstl_objid` int(11) NOT NULL,
  `zbstl_tagid` int(11) NOT NULL,
  PRIMARY KEY (`ID`),
  KEY `zbstl_objid` (`zbstl_objid`),
  KEY `zbstl_tagid` (`zbstl_tagid`),
  KEY `zbstl_tagid+zbstl_objtype` (`zbstl_tagid`,`zbstl_objtype`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_zbs_tax_table`;
CREATE TABLE `SERVMASK_PREFIX_zbs_tax_table` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `zbs_site` int(11) DEFAULT NULL,
  `zbs_team` int(11) DEFAULT NULL,
  `zbs_owner` int(11) NOT NULL,
  `zbsc_tax_name` varchar(100) DEFAULT NULL,
  `zbsc_rate` decimal(18,2) NOT NULL DEFAULT 0.00,
  `zbsc_created` int(14) NOT NULL,
  `zbsc_lastupdated` int(14) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_zbs_temphash`;
CREATE TABLE `SERVMASK_PREFIX_zbs_temphash` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `zbs_site` int(11) DEFAULT NULL,
  `zbs_team` int(11) DEFAULT NULL,
  `zbs_owner` int(11) NOT NULL,
  `zbstemphash_status` int(11) DEFAULT -1,
  `zbstemphash_objtype` varchar(50) NOT NULL,
  `zbstemphash_objid` int(11) DEFAULT NULL,
  `zbstemphash_objhash` varchar(256) DEFAULT NULL,
  `zbstemphash_created` int(14) NOT NULL,
  `zbstemphash_lastupdated` int(14) NOT NULL,
  `zbstemphash_expiry` int(14) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_zbs_tracking`;
CREATE TABLE `SERVMASK_PREFIX_zbs_tracking` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `zbs_site` int(11) DEFAULT NULL,
  `zbs_team` int(11) DEFAULT NULL,
  `zbs_owner` int(11) NOT NULL,
  `zbst_contactid` int(11) NOT NULL,
  `zbst_action` varchar(50) NOT NULL,
  `zbst_action_detail` longtext NOT NULL,
  `zbst_referrer` varchar(300) NOT NULL,
  `zbst_utm_source` varchar(200) NOT NULL,
  `zbst_utm_medium` varchar(200) NOT NULL,
  `zbst_utm_name` varchar(200) NOT NULL,
  `zbst_utm_term` varchar(200) NOT NULL,
  `zbst_utm_content` varchar(200) NOT NULL,
  `zbst_created` int(14) NOT NULL,
  `zbst_lastupdated` int(14) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_zbs_transactions`;
CREATE TABLE `SERVMASK_PREFIX_zbs_transactions` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `zbs_site` int(11) DEFAULT NULL,
  `zbs_team` int(11) DEFAULT NULL,
  `zbs_owner` int(11) NOT NULL,
  `zbst_status` varchar(50) NOT NULL,
  `zbst_type` varchar(50) DEFAULT NULL,
  `zbst_ref` varchar(120) NOT NULL,
  `zbst_origin` varchar(100) DEFAULT NULL,
  `zbst_parent` int(11) DEFAULT NULL,
  `zbst_hash` varchar(64) DEFAULT NULL,
  `zbst_title` varchar(200) DEFAULT NULL,
  `zbst_desc` varchar(200) DEFAULT NULL,
  `zbst_date` int(14) DEFAULT NULL,
  `zbst_customer_ip` varchar(45) DEFAULT NULL,
  `zbst_currency` varchar(4) NOT NULL DEFAULT '-1',
  `zbst_net` decimal(18,2) NOT NULL DEFAULT 0.00,
  `zbst_fee` decimal(18,2) NOT NULL DEFAULT 0.00,
  `zbst_discount` decimal(18,2) DEFAULT 0.00,
  `zbst_shipping` decimal(18,2) DEFAULT 0.00,
  `zbst_shipping_taxes` varchar(40) DEFAULT NULL,
  `zbst_shipping_tax` decimal(18,2) DEFAULT 0.00,
  `zbst_taxes` varchar(40) DEFAULT NULL,
  `zbst_tax` decimal(18,2) DEFAULT 0.00,
  `zbst_total` decimal(18,2) NOT NULL DEFAULT 0.00,
  `zbst_date_paid` int(14) DEFAULT NULL,
  `zbst_date_completed` int(14) DEFAULT NULL,
  `zbst_created` int(14) NOT NULL,
  `zbst_lastupdated` int(14) NOT NULL,
  PRIMARY KEY (`ID`),
  KEY `status` (`zbst_status`),
  KEY `ref` (`zbst_ref`),
  KEY `transtype` (`zbst_type`),
  KEY `transorigin` (`zbst_origin`),
  KEY `parent` (`zbst_parent`),
  KEY `hash` (`zbst_hash`),
  KEY `date` (`zbst_date`),
  KEY `title` (`zbst_title`),
  KEY `created` (`zbst_created`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


DROP TABLE IF EXISTS `SERVMASK_PREFIX_zbs_workflows`;
CREATE TABLE `SERVMASK_PREFIX_zbs_workflows` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `zbs_site` int(11) NOT NULL,
  `zbs_team` int(11) NOT NULL,
  `zbs_owner` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` varchar(600) DEFAULT NULL,
  `category` varchar(255) NOT NULL,
  `triggers` longtext NOT NULL,
  `initial_step` varchar(255) NOT NULL,
  `steps` longtext NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(14) NOT NULL DEFAULT 1,
  `created_at` int(14) DEFAULT NULL,
  `updated_at` int(14) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `name` (`name`),
  KEY `active` (`active`),
  KEY `category` (`category`),
  KEY `created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

